pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address newDistributor) public {
        vm.assume(newDistributor != address(0));

        bool referenceOk;
        try c.setRewardDistributor(newDistributor) {
            referenceOk = true;
        } catch {
            referenceOk = false;
        }

        assertTrue(referenceOk);
    }
}
